            "anyOf": [
                {
                    "type": "null"
                },
                {
                    "type": "string",
                    "maxLength": 0
                }
            ]
        },
        "organizationIsRequiredWhenRegistrantTypeIsOrganization": {
            "not": {
                "properties": {
                    "extra": {
                        "type": "object",
                        "properties": {
                            "fr": {
                                "type": "object",
