                                    "registrantType": {
                                        "type": "string",
                                        "enum": [
                                            "organization"
                                        ]
                                    }
                                }
                            }
                        }
                    },
                    "organization": {
                        "$ref": "#/definitions/empty"
                    }
                }
            }
        }
    },
    "type": "object",
    "allOf": [
        {
            "$ref": "#/definitions/organizationIsRequiredWhenRegistrantTypeIsOrganization"
        },
        {
            "type": "object",
            "required": [
                "extra"
            ],
            "properties": {
                "organization": {
                    "type": "string",
                    "not": {
                        "pattern": "[^a-zA-Z0-9.,()@&' -]"
                    },
                    "maxLength": 100
                },
                "extra": {
                    "type": "object",
                    "properties": {
                        "fr": {
                            "type": "object",
                            "properties": {
                                "sirenSiret": {
                                    "type": "string",
                                    "pattern": "^[0-9]*$",
                                    "anyOf": [
                                        {
                                            "minLength": 9,
                                            "maxLength": 9
                                        },
                                        {
                                            "minLength": 14,
                                            "maxLength": 14
                                        },
                                        {
                                            "$ref": "#/definitions/empty"
                                        }
                                    ]
                                },
                                "registrantType": {
                                    "type": "string",
                                    "enum": [
                                        "individual",
                                        "organization"
                                    ]
                                },
                                "registrantVatId": {
                                    "type": "string",
                                    "anyOf": [
                                        {
                                            "pattern": "^(AT)U[0-9]{8}$"
                                        },
                                        {
                                            "pattern": "^(BE)0[0-9]{9}$"
                                        },
                                        {
                                            "pattern": "^(BG)[0-9]{9,10}$"
                                        },
                                        {
                                            "pattern": "^(CY)[0-9]{8}L$"
