                                        },
                                        {
                                            "pattern": "^(EE)[0-9]{9}$"
                                        },
                                        {
                                            "pattern": "^(EL|GR)[0-9]{9}$"
                                        },
                                        {
                                            "pattern": "^(ES)[0-9A-Z][0-9]{7}[0-9A-Z]$"
                                        },
                                        {
                                            "pattern": "^(FI)[0-9]{8}$"
                                        },
                                        {
                                            "pattern": "^(FR)[0-9A-Z]{2}[0-9]{9}$"
                                        },
                                        {
                                            "pattern": "^(GB)([0-9]{9}([0-9]{3})?|(GD|HA)[0-9]{3})$"
                                        },
                                        {
                                            "pattern": "^(HR)[0-9]{11}$"
                                        },
                                        {
                                            "pattern": "^(HU)[0-9]{8}$"
                                        },
                                        {
                                            "pattern": "^(IE)([0-9][0-9A-Z+*][0-9]{5}[A-Z]|[0-9]{7}[0-9A-Z]{1,2})$"
                                        },
